    seed = sum((i + 1) * v for i, v in enumerate(flat)) + h * 1009 + w * 9176
    for k, (r0, c0) in enumerate(((0,w),(h,0),(h,w)), 1):
        cells = flat[:]
        random.Random(seed + k * 104729).shuffle(cells)
        for i in range(h):
            for j in range(w):
                out[r0+i][c0+j] = cells[i*w+j]
    return out
